// Posty — event router. The Slack Trigger is any_event, so everything the app subscribes
// to lands here: reaction_added, message.channels, message.im. Route once, so downstream
// filters test one plain string instead of poking at fields a given event may not have.

const e = $input.first().json;
const NEWPOST = 'C1SJE7404';
const RELEASEME = 'CC9EG3K8C';
const QU_RE = /QU[\s]*[-_]?[\s]*(\d{4,6})/i;

// A QU- or QU_ prefix with no digits: the agreed convention for a project whose code is
// not assigned yet. Tracked under a synthetic key so it ages and can be rocketed.
const QU_MARKER_RE = /QU[\s]*[-_]/i;

// Only these people announce projects. Policy list set by Tara 2026-08-31; mirrored in
// code/parse.js. ADD NEW POST ENGINEERS HERE ON THEIR FIRST DAY — until someone is on this
// list their posts are invisible to Posty, which is intended, and also how this list goes
// quietly wrong. A skipped post that carried a QU is reported with its code below, so the
// omission shows up in the execution list instead of vanishing.
const POST_ENGINEERS = {
  'U025597KZ':   'regie',
  'U029T6N7U':   'philip',
  'U026N6E1R':   'tara',
  'U04DLRCAA':   'glenn',
  'U6UAKUP08':   'whannie',
  'U026LMLM4':   'rico',
  'U026N9FV9':   'vener',
  'U026N7KR7':   'topet',
  'U026MTBLM':   'richard',
  'U026R9SUQ':   'eddie boy',
  'U08V83R45QV': 'alec elijah',
  'U08V3CKDGJF': 'howard',
};
const isDm = (ch) => typeof ch === 'string' && ch.charAt(0) === 'D';

function ignore(reason) {
  return [{ json: { kind: 'IGNORE', reason, event_type: e.type || null } }];
}

if (e.type === 'reaction_added') {
  if (e.reaction !== 'rocket') return ignore('reaction is not rocket');
  if (!e.item || !e.item.channel) return ignore('reaction has no item');
  // Two valid origins: the intake post itself, or a DM Posty sent about that project.
  // resolve-release.js works out which by matching source_ts then notify_ts.
  const ch = e.item.channel;
  if (ch !== NEWPOST && !isDm(ch)) return ignore('rocket not in #newpostprojects or a DM');
  return [{ json: { kind: 'RELEASE', user: e.user, item_ts: e.item.ts, from_dm: isDm(ch) } }];
}

if (e.type === 'message') {
  // Posty writes to #releaseme and DMs people. Without this guard it would eventually
  // see its own messages and act on them.
  if (e.bot_id) return ignore('bot message');

  // A deleted intake post leaves an index row pointing at a message that no longer
  // exists. Left alone, a repost is treated as a re-announcement, no new row is written,
  // and a rocket on the new post matches nothing — the project becomes permanently
  // unreleasable. Catch the deletion so the row can be re-registered.
  if (e.subtype === 'message_deleted') {
    if (!e.deleted_ts) return ignore('deletion with no deleted_ts');
    if (e.channel === NEWPOST) {
      return [{ json: { kind: 'DELETED_POST', deleted_ts: String(e.deleted_ts) } }];
    }
    // Deleting Posty's post in #releaseme means the release did not actually happen —
    // this is the undo for a mistaken rocket. Without it a wrong release is permanent:
    // the row stays RELEASED and the dedupe (§7 step 5) blocks it from ever being
    // released again.
    if (e.channel === RELEASEME) {
      return [{ json: { kind: 'RELEASE_UNDONE', deleted_ts: String(e.deleted_ts) } }];
    }
    return ignore('deletion in an unrelated channel');
  }

  if (e.subtype) return ignore('message subtype: ' + e.subtype);
  if (!e.user) return ignore('no user on message');

  // A DM to Posty is a request for that person's open projects. There is exactly one
  // intent, so there is nothing to parse — any DM means "list mine".
  if (isDm(e.channel) || e.channel_type === 'im') {
    // Two intents, distinguished by one keyword. No language model: "digest" or not is a
    // decision a regex makes correctly every time, and a wrong guess here would send the
    // whole open-projects list to someone who asked for their own.
    if (/\bdigests?\b/i.test(String(e.text || ''))) {
      return [{ json: { kind: 'DIGEST_REQUEST', user: e.user, channel: e.channel } }];
    }
    // Tidy up the DM. Deletes only Posty's OWN messages, only in this conversation.
    if (/\bclear\b/i.test(String(e.text || ''))) {
      return [{ json: { kind: 'CLEAR_REQUEST', user: e.user, channel: e.channel } }];
    }
    return [{ json: { kind: 'LIST_REQUEST', user: e.user, channel: e.channel } }];
  }

  if (e.channel !== NEWPOST) return ignore('message not in #newpostprojects');

  // Not a post engineer -> not a project announcement, whatever the message contains.
  if (!Object.prototype.hasOwnProperty.call(POST_ENGINEERS, String(e.user).trim())) {
    const stray = String(e.text || '').match(QU_RE);
    return ignore(stray
      ? 'not a post engineer, and the message carried QU-' + stray[1] + ' (not tracked)'
      : 'not a post engineer');
  }

  // A project is a post with a QU code. Codeless posts are left alone — they still show
  // in the digest's "needs manual check" section, but they are not tracked, because
  // nothing can be counted, aged or released without an identifier. Post engineers write
  // a QU code, always.
  const text = e.text || '';
  const m = text.match(QU_RE);

  if (m) {
    return [{ json: { kind: 'NEW_PROJECT', user: e.user, qu_number: m[1], text, ts: e.ts } }];
  }

  // Marked as a project but not coded yet. Synthetic key from the post's own ts; refuse
  // an implausible ts, since a shared key would collapse every uncoded project into one.
  if (QU_MARKER_RE.test(text) && /^\d{6,}(\.\d+)?$/.test(String(e.ts || '').trim())) {
    return [{ json: { kind: 'NEW_PROJECT', user: e.user,
                      qu_number: 'NOQU-' + String(e.ts).trim(), text, ts: e.ts,
                      synthetic: true } }];
  }

  return ignore('no QU code and no QU- marker');
}

return ignore('unhandled event type');

// Posty — release decision. code/resolve-release.js pasted verbatim, tested by
// ./scripts/test-nodes. Edit in code/, run the tests, paste back.

// Posty — Workflow 2's decision node, as a testable module.
//
// Given a reaction_added event and the current index, decides what happens. Pure: no I/O,
// no posting. The node that actually posts sits downstream of this one, so every path that
// could put a message into #releaseme is decided here and can be tested offline.
//
// Handoff §7 Workflow 2. The order of the checks below is the order in §7 and matters:
// a released row must be dropped BEFORE anything reaches the poster.



const DECISIONS = {
  POST: 'POST',                       // repost source_text verbatim, then mark released
  DROP_RELEASED: 'DROP_RELEASED',     // already shipped — this is the dedupe
  DROP_CANCELLED: 'DROP_CANCELLED',   // cancelled projects are never reposted
  PENDING: 'PENDING',                 // not indexed yet; retry after the nightly refresh
};

// Slack ts values are identifiers, not numbers. Compare as trimmed strings — a numeric
// compare would make 1788163608.395249 and 1788163608.39525 look equal, which is exactly
// the silent failure the text-formatted Sheet column exists to prevent.
// The stored source_text is decoded for readability. Slack expects &, < and > escaped in
// chat.postMessage, so re-escape on the way out. This makes the posted bytes identical to
// what was verified live on 2026-08-31, when the round-trip was confirmed correct.
function escapeForSlack(text) {
  return String(text == null ? '' : text)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function sameTs(a, b) {
  return String(a == null ? '' : a).trim() === String(b == null ? '' : b).trim();
}

function resolveRelease(input) {
  const { event = {}, indexRows = [], nowIso } = input;

  const itemTs = event.item ? event.item.ts : null;
  const itemChannel = event.item ? event.item.channel : null;

  // A rocket can arrive from two places, and both must resolve to the same project:
  //   - on the intake post in #newpostprojects  -> matches source_ts
  //   - on the DM Posty sent about that project -> matches notify_ts
  // notify_ts is recorded when Posty DMs about a project, so neither route needs a
  // conversations.history call to work out what was reacted to (§8, no history on the
  // hot path). source_ts is checked first: it is the canonical identifier, and a DM is
  // only ever a pointer back to it.
  const row = indexRows.find((r) => sameTs(r.source_ts, itemTs))
           || indexRows.find((r) => r.notify_ts && sameTs(r.notify_ts, itemTs));

  // §7 step 4. The reaction arrived before the nightly refresh indexed the post. Park it;
  // do NOT call conversations.history to resolve the text here — avoiding that call on the
  // hot path is the entire reason this design is event-driven rather than polling (§8).
  if (!row) {
    return {
      decision: DECISIONS.PENDING,
      reason: 'no index row matches source_ts or notify_ts ' + itemTs,
      pending: {
        item_ts: String(itemTs == null ? '' : itemTs),
        item_channel: itemChannel || '',
        reacted_by: event.user || '',
        event_ts: String(event.event_ts == null ? '' : event.event_ts),
        first_seen: nowIso,
        retry_count: 0,
        resolved: 'FALSE',
      },
    };
  }

  // §7 step 5 — the dedupe. Keyed on the row's status, deliberately NOT on event_ts:
  // a second rocket days later carries a completely different event_ts and must still be
  // dropped. Verified live on 2026-08-31, when one message produced two reaction_added
  // events 18 seconds apart.
  if (row.status === 'RELEASED') {
    return { decision: DECISIONS.DROP_RELEASED, row,
             reason: 'QU-' + row.qu_number + ' is already RELEASED' };
  }

  // §7 step 6 / §9 rule 1. Reposting a cancelled project would tell Accounting to bill
  // something that never went out.
  if (row.status === 'CANCELLED') {
    return { decision: DECISIONS.DROP_CANCELLED, row,
             reason: 'QU-' + row.qu_number + ' is CANCELLED' };
  }

  // UNTRACKED rows carry no QU number, so there is nothing to mark released and nothing
  // that would join back to Accounting. Park rather than post.
  if (!row.qu_number) {
    return { decision: DECISIONS.PENDING, row,
             reason: 'row has no QU number (UNTRACKED)',
             pending: {
               item_ts: String(itemTs == null ? '' : itemTs),
               item_channel: itemChannel || '',
               reacted_by: event.user || '',
               event_ts: String(event.event_ts == null ? '' : event.event_ts),
               first_seen: nowIso,
               retry_count: 0,
               resolved: 'FALSE',
             } };
  }

  // §7 step 7. Repost source_text VERBATIM. This is the whole point: it guarantees the QU
  // number and title match the intake post exactly, which is what kills the format drift
  // between posters — glenn writes `QU / Agency / Producer / Client / Title` while rico
  // writes `QU / Client "Title" / Producer / Studio M Recording`.
  return {
    decision: DECISIONS.POST,
    row,
    text: escapeForSlack(row.source_text),
    qu_number: row.qu_number,
    reason: 'QU-' + row.qu_number + ' is ' + (row.status || 'OPEN') + ', reposting',
  };
}

const event = $('Slack Trigger').first().json;
const indexRows = $('Read Index').all().map((i) => i.json);
const out = resolveRelease({ event, indexRows, nowIso: new Date().toISOString() });
return [{ json: out }];

// Write-back after a successful repost. release_ts is the ts of the message POSTY created
// (§6), not the intake post's ts. The n8n Slack node returns message_timestamp and
// message.ts — never `ts`. Guessing that field cost a live bug on 2026-08-31.
const resolved = $('Resolve Release').first().json;
const posted = $input.first().json;

// Manila-local date, matching code/parse.js. UTC+8, no DST. The regex guard is
// load-bearing: Number('') is 0, which passes Number.isFinite and silently yields
// 1970-01-01. A blank date is honest; the epoch is a lie that looks like data.
function tsToDate(t) {
  t = String(t == null ? '' : t).trim();
  if (!/^\d{6,}(\.\d+)?$/.test(t)) return '';
  return new Date(Number(t.split('.')[0]) * 1000 + 8 * 3600 * 1000).toISOString().slice(0, 10);
}
function slackTs(resp) {
  return String(resp.message_timestamp || (resp.message && resp.message.ts) || '').trim();
}

const ts = slackTs(posted);
const row = {
  qu_number: resolved.qu_number,
  released: 'TRUE',
  release_ts: ts,
  release_date: tsToDate(ts),
  status: 'RELEASED',
  last_seen: new Date().toISOString(),
};

// Still RELEASED even if the ts could not be read. The message is already posted and
// cannot be unposted, so the dedupe (§7 step 5, keyed on status) must hold or the next
// rocket duplicates it in front of Accounting. A data gap beats a visible mess.
if (!ts) row.note = 'WARNING: could not read the posted message ts from the Slack response';

return [{ json: row }];

const r = $input.first().json;
return [{ json: { dropped: true, decision: r.decision, reason: r.reason,
                  qu_number: r.row ? r.row.qu_number : null } }];

// A new project post. Decide whether it is genuinely new before announcing it.
//
//   no row              -> ANNOUNCE, brand new project
//   row, status OPEN    -> SKIP. A re-announcement keeps the original row untouched
//                          (§7 step 4); DMing "You started" for a repost would be wrong.
//   row, status DELETED -> ANNOUNCE. The original post was deleted, so this repost is how
//                          the project exists now. The row is refreshed entirely, dates
//                          included: the channel's job is an accurate current list of
//                          ongoing projects, not forensic aging. If a typo went unnoticed
//                          for weeks, the clock restarting is a fair consequence.
const req = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);

const existing = rows.find((r) =>
  String(r.qu_number || '').trim() === String(req.qu_number).trim());

if (existing && String(existing.status || '').trim() !== 'DELETED') {
  return [{ json: { kind: 'SKIP',
    reason: 'QU-' + req.qu_number + ' is already indexed (' + existing.status + ')' } }];
}

return [{ json: { kind: 'ANNOUNCE', user: req.user, qu_number: req.qu_number,
                  text: req.text, ts: req.ts, reregistered: Boolean(existing) } }];

// Index the project immediately, rather than waiting for the nightly refresh. This is why
// PENDING is now rare: the row exists the moment the post does, so a rocket seconds later
// already has something to resolve against.
//
// notify_ts is the DM Posty just sent. Recording it lets a rocket on that DM resolve to
// this same project without any conversations.history call (§8).
const p = $('Resolve New Project').first().json;
const dm = $input.first().json;

// Slack escapes &, < and > in event text. Store decoded; escape again on the way out.
// Keeps the Sheet readable without changing the bytes Posty posts. See code/parse.js.
function decodeEntities(t) {
  return String(t == null ? '' : t)
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}
function escapeForSlack(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}


// Manila-local date, matching code/parse.js. UTC+8, no DST. The regex guard is
// load-bearing: Number('') is 0, which passes Number.isFinite and silently yields
// 1970-01-01. A blank date is honest; the epoch is a lie that looks like data.
function tsToDate(t) {
  t = String(t == null ? '' : t).trim();
  if (!/^\d{6,}(\.\d+)?$/.test(t)) return '';
  return new Date(Number(t.split('.')[0]) * 1000 + 8 * 3600 * 1000).toISOString().slice(0, 10);
}
function slackTs(resp) {
  return String(resp.message_timestamp || (resp.message && resp.message.ts) || '').trim();
}

return [{ json: {
  qu_number: p.qu_number,
  source_channel: 'C1SJE7404',
  source_ts: String(p.ts),
  source_text: decodeEntities(p.text),
  posted_date: tsToDate(p.ts),
  released: 'FALSE',
  release_ts: '',
  release_date: '',
  status: 'OPEN',
  age_days: '',
  last_seen: new Date().toISOString(),
  notify_ts: slackTs(dm),
  posted_by: p.user,
} }];

// Build the requester's open-project list. One message per project, so each can be
// rocketed individually — a single combined message would give no way to pick one.
const CAP = 25;
const req = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);

// Slack escapes &, < and > in event text. Store decoded; escape again on the way out.
// Keeps the Sheet readable without changing the bytes Posty posts. See code/parse.js.
function decodeEntities(t) {
  return String(t == null ? '' : t)
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}
function escapeForSlack(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}


function ageDays(posted, today) {
  const a = Date.parse(posted + 'T00:00:00Z'), b = Date.parse(today + 'T00:00:00Z');
  return (Number.isFinite(a) && Number.isFinite(b)) ? Math.round((b - a) / 86400000) : null;
}
const today = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);

const mine = rows.filter((r) =>
  String(r.posted_by || '').trim() === String(req.user).trim() &&
  String(r.status || '').trim() === 'OPEN' &&
  String(r.qu_number || '').trim() !== '');

mine.sort((a, b) => String(a.posted_date).localeCompare(String(b.posted_date)));
const shown = mine.slice(0, CAP);
const hidden = mine.length - shown.length;

let header;
if (mine.length === 0) {
  header = 'You have no open projects. Nothing of yours is waiting to be released.';
} else {
  header = 'You have ' + mine.length + ' open project' + (mine.length === 1 ? '' : 's') +
    '. Rocket any message below to release it.';
  if (hidden > 0) header += ' Showing the ' + shown.length + ' oldest — ' + hidden + ' more not shown.';
}

// The header carries no qu_number, so the write-back downstream skips it.
const out = [{ json: { is_header: true, qu_number: '', text: header } }];
for (const r of shown) {
  const age = ageDays(r.posted_date, today);
  out.push({ json: { is_header: false, qu_number: r.qu_number,
                     text: escapeForSlack(r.source_text) + (age === null ? '' : '  —  ' + age + 'd') } });
}
return out;

// Record the ts of each list message as that project's notify_ts, so rocketing the DM
// resolves back to the project. Pair responses to inputs by index — the Slack node runs
// once per item and preserves order.
const inputs = $('Build List').all().map((i) => i.json);
const resps = $input.all().map((i) => i.json);

// Manila-local date, matching code/parse.js. UTC+8, no DST. The regex guard is
// load-bearing: Number('') is 0, which passes Number.isFinite and silently yields
// 1970-01-01. A blank date is honest; the epoch is a lie that looks like data.
function tsToDate(t) {
  t = String(t == null ? '' : t).trim();
  if (!/^\d{6,}(\.\d+)?$/.test(t)) return '';
  return new Date(Number(t.split('.')[0]) * 1000 + 8 * 3600 * 1000).toISOString().slice(0, 10);
}
function slackTs(resp) {
  return String(resp.message_timestamp || (resp.message && resp.message.ts) || '').trim();
}

const out = [];
for (let i = 0; i < resps.length; i++) {
  const src = inputs[i];
  if (!src || src.is_header || !src.qu_number) continue;   // header is not a project
  const ts = slackTs(resps[i]);
  if (!ts) continue;                                        // no ts, nothing to record
  out.push({ json: { qu_number: src.qu_number, notify_ts: ts,
                      last_seen: new Date().toISOString() } });
}
return out;

// Mark the row whose intake post was just deleted.
//
// Deliberately status-agnostic. An earlier version only touched OPEN rows, on the theory
// that a RELEASED project should not be reopened — but marking a row DELETED never
// reopens it, so that guard bought nothing and created an ordering trap: delete the
// #releaseme post first and it worked, delete the intake post first and it silently did
// nothing. One rule now: the intake post is gone, so the row stops counting.
//
// The row is kept, not removed. status becomes DELETED, which drops it out of the open
// list and the digest, while release_ts and posted_date survive as history — useful if
// Accounting ever asks why a QU has no release.
//
// UNTRACKED rows have no qu_number, so appendOrUpdate cannot match them and they cannot
// be cleaned this way. Rare, and they are already excluded from every count.
const req = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);

const row = rows.find((r) =>
  String(r.source_ts || '').trim() === String(req.deleted_ts).trim());

if (!row) return [{ json: { kind: 'NOOP', reason: 'no index row for deleted ts ' + req.deleted_ts } }];
if (!row.qu_number)
  return [{ json: { kind: 'NOOP', reason: 'untracked row has no key to update' } }];
if (String(row.status || '').trim() === 'DELETED')
  return [{ json: { kind: 'NOOP', reason: 'row is already DELETED' } }];

return [{ json: { kind: 'MARK', qu_number: row.qu_number, status: 'DELETED',
                  was_status: row.status || '', last_seen: new Date().toISOString() } }];

// Strip the routing key so only the columns we mean to change are written.
const r = $input.first().json;
return [{ json: { qu_number: r.qu_number, status: r.status, last_seen: r.last_seen } }];

// Revert a release whose #releaseme post was deleted.
//
// Only rows that are actually RELEASED, matched on release_ts — the ts of the message
// Posty created. A CANCELLED row is left alone: deleting the cancellation notice does not
// un-cancel a project.
//
// notify_ts is deliberately kept. The DM Posty sent still exists, so rocketing it again
// must still resolve to this project — that is the whole point of an undo.
const req = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);

const row = rows.find((r) =>
  String(r.release_ts || '').trim() === String(req.deleted_ts).trim());

if (!row) return [{ json: { kind: 'NOOP', reason: 'no row released as ts ' + req.deleted_ts } }];
if (String(row.status || '').trim() !== 'RELEASED')
  return [{ json: { kind: 'NOOP', reason: 'row is ' + row.status + ', not reverting' } }];
if (!row.qu_number)
  return [{ json: { kind: 'NOOP', reason: 'no qu_number to match on' } }];

return [{ json: { kind: 'REVERT', qu_number: row.qu_number,
                  status: 'OPEN', released: 'FALSE',
                  release_ts: '', release_date: '',
                  last_seen: new Date().toISOString() } }];

// Strip the routing key; write only the columns being reverted.
const r = $input.first().json;
return [{ json: { qu_number: r.qu_number, status: r.status, released: r.released,
                  release_ts: r.release_ts, release_date: r.release_date,
                  last_seen: r.last_seen } }];

// Hand the requester to Workflow 3. It resolves recipients itself, so the digest a
// person asks for is built by exactly the same code as the scheduled one.
//
// Read from Classify Event by name, NOT from $input. Reading $input meant that inserting
// any node upstream silently replaced the payload — an ack reaction did exactly that, the
// user went undefined, and Workflow 3 fell through to its scheduled gate and sent nothing.
return [{ json: { user: $('Classify Event').first().json.user } }];

// Select which messages to delete.
//
// TWO HARD LIMITS, both deliberate:
//   * only messages whose author is Posty (U0BTV2PGDSM) — a person's own messages are
//     never touched, even though the bot token could not delete them anyway
//   * only this one DM conversation, never a channel
//
// Deleting the list messages also orphans their notify_ts values in the index. That is
// harmless: a notify_ts pointing at a deleted message simply never matches, and the
// project is still releasable from its post in #newpostprojects or from a fresh list.
const POSTY = 'U0BTV2PGDSM';
const body = $input.first().json;

if (!body.ok) {
  return [{ json: { error: true, reason: 'conversations.history failed: ' + body.error } }];
}

const mine = (body.messages || []).filter((m) => m.user === POSTY || m.bot_id);
const channel = $('Classify Event').first().json.channel;

if (!mine.length) return [{ json: { nothing: true, channel } }];

return mine.map((m) => ({ json: { channel, ts: m.ts, total: mine.length } }));

// One confirmation after the deletes. $input carries one item per chat.delete call.
const results = $input.all().map((i) => i.json);
const ok = results.filter((r) => r && r.ok).length;
const failed = results.length - ok;

let text = 'Cleared ' + ok + ' message' + (ok === 1 ? '' : 's') + '.';
if (failed) text += ' ' + failed + ' could not be deleted.';
if (!ok && !failed) text = 'Nothing to clear.';

